def _extract_counter_values(data, key, path=None):
    """
    Recursively search for values of the specified key in a nested dictionary and include their hierarchical path.
    Args:
        data (dict or list): The nested dictionary or list to search through.
        key (str): The key whose values need to be extracted.
        path (list, optional): The hierarchical path to the current level in the nested structure. Defaults = None.
    Returns:
        list: A list of dictionaries containing the values of the specified key and their hierarchical paths.
    Examples:
        data = {
                'BTS': {
                    'MRBTS-1': {
                        'NRBTS-1': {
                            'NRCELL-1': {
                                'PDCPC': {
                                    'M55350C20022': {'1732786500': 0, '1732786800': 0},
                                    'M55350C20024': {'1732786500': 0, '1732786800': 0},
                                    ...,
                                    'M55350C20037': {'1732786500': 0, '1732786800': 0}
                                    },
                                'NLRLC': {
                                    'M55310C20012': {'1732786500': 0, '1732786800': 0},
                                    'M55310C20019': {'1732786500': 0, '1732786800': 0},
                                    ...,
                                    'M55310C20021': {'1732786500': 0, '1732786800': 0}
                                    }
                                },
                            'NRCELL-2': {
                                'NLRLC': {
                                    'M55310C20014': {'1732786500': 0, '1732786800': 0},
                                    'M55310C20019': {'1732786500': 0, '1732786800': 0},
                                    ...,
                                    'M55310C20024': {'1732786500': 0, '1732786800': 0}
                                    },
                                'PDCPC': {
                                    'M55350C20045': {'1732786500': 0, '1732786800': 0},
                                    'M55350C20042': {'1732786500': 0, '1732786800': 0},
                                    ...
                                    'M55350C20052': {'1732786500': 0, '1732786800': 0}
                                    }
                                }
                            }
                        }
                    }
                }
        key = 'M55310C20019'
        Returns: [
                    {'1732694400': 0, '1732694700': 0, 'dict_path': 'BTS/MRBTS-1/NRBTS-1/NRCELL-2/NLRLC/M55310C20019'},
                    {'1732694400': 0, '1732694700': 0, 'dict_path': 'BTS/MRBTS-1/NRBTS-1/NRCELL-1/NLRLC/M55310C20019'}
                    ]
    """
    if path is None:
        path = []
    values = []
    if isinstance(data, dict):
        for k, v in data.items():
            new_path = path + [k]
            if k == key:
                v['dict_path'] = new_path
                values.append(v)
            else:
                values.extend(_extract_counter_values(v, key, new_path))
    elif isinstance(data, list):
        for item in data:
            values.extend(_extract_counter_values(item, key, path))
    if values:
        for i in values:
            if isinstance(i['dict_path'], list):
                i['dict_path'] = '/'.join(i['dict_path'])
    return values


def _evaluate_condition(value, operator_str, exp_value):
    """Evaluate the condition dynamically."""
    ops = {
        '==': operator.eq,
        '>': operator.gt,
        '<': operator.lt,
        '>=': operator.ge,
        '<=': operator.le,
        '!=': operator.ne
    }
    return ops[operator_str](value, exp_value)


def _prepare_data_to_compare(cnt_value, counters_to_compare=None, min_val=None, max_val=None):
    """ Prepares and structures counter data for comparison by organizing it into a dictionary
    with timestamps as keys and tuples of counter values as values.
    Args:
        cnt_value (dict): A nested dictionary containing counters and their values.
                          Example:
                          {
                              'counters': {
                                  'M55310C20019': {'1732786500': 0, '1732786800': 1},
                                  'M55310C20020': {'1732786500': 2, '1732786800': 3}
                              }
                          }
        counters_to_compare (list, optional): A list of counter IDs to include in the result.
                                              If None, all counters are included. Defaults to None.
        min_val (int, optional): A minimum value to include as 'MIN_VAL' in the result. Defaults to None.
        max_val (int, optional): A maximum value to include as 'MAX_VAL' in the result. Defaults to None.
    Returns:
        dict: A dictionary where:
              - Keys are timestamps.
              - Values are tuples of counter values, optionally including 'MIN_VAL' and 'MAX_VAL'.
              Example:
              {
                  1732786500: (('MIN_VAL', 100), ('M55310C20019', 0), ('M55310C20020', 2), ('MAX_VAL', 200)),
                  1732786800: (('MIN_VAL', 100), ('M55310C20019', 1), ('M55310C20020', 3), ('MAX_VAL', 200))
              }
    Raises:
        ValueError: If `counters_to_compare` contains counters not present in `cnt_value`.
    Example:
        cnt_value = {
            'counters': {
                'M55310C20019': {'1732786500': 0, '1732786800': 1},
                'M55310C20020': {'1732786500': 2, '1732786800': 3}
            }
        }
        counters_to_compare = ['M55310C20019', 'M55310C20020']
        min_val = 100
        max_val = 200

        result = _prepare_data_to_compare(cnt_value, counters_to_compare, min_val, max_val)
        # Output:
        # {
        #     1732786500: (('MIN_VAL', 100), ('M55310C20019', 0), ('M55310C20020', 2), ('MAX_VAL', 200)),
        #     1732786800: (('MIN_VAL', 100), ('M55310C20019', 1), ('M55310C20020', 3), ('MAX_VAL', 200))
        # }
    """
    _, counters_data = next(iter(cnt_value.items()))

    timestamps = set()
    for counter in counters_to_compare:
        if counter in counters_data:
            timestamps.update(counters_data[counter].keys())
    if min_val is not None:
        counters_to_compare.insert(0, 'MIN_VAL')
    if max_val is not None:
        counters_to_compare.append('MAX_VAL')
    result = dict()
    for timestamp in sorted(timestamps):
        result[timestamp] = tuple(
            (counter, counters_data[counter].get(timestamp, None))
            for counter in counters_to_compare
            if counter in counters_data
        )
    if min_val:
        for k, v in result.items():
            result[k] = (('MIN_VAL', int(min_val)),) + result[k]
    if max_val:
        for k, v in result.items():
            result[k] = result[k] + (('MAX_VAL', int(max_val)),)

    # removing first timestamp after counter activation - compliant with test requirement
    first_timestamp = next(iter(result))
    result.pop(first_timestamp)
    return result


def get_counters(counters_and_expected_values, timeout=600):
    """ Retrieves PM counter values from BTS.
    Args:
        counters_and_expected_values (Union[List[str], Dict]): Either:
            - List of counter IDs to retrieve
            - Dictionary containing counter IDs as keys and expected values as values
        connection (AdminConnection): AdminConnection object or string name alias.
        timeout (int, optional): Maximum time to wait for response in seconds. Defaults to 600.
    Returns:
        dict: Dictionary containing response with counter values from BTS.
    Example:
        # Using list of counters
        counters = ['M55310C20019', 'M55350C20022']
        result = get_counters(counters)

        # Using dictionary with expected values
        counters = {
            'M55310C20019': {'operator': '==', 'value': '0'},
            'M55350C20022': {'operator': '>', 'value': '0'}
        }
        result = get_counters(counters)
    """
    if isinstance(counters_and_expected_values, list) or isinstance(counters_and_expected_values, tuple):
        counters_to_get = ','.join(counters_and_expected_values)
    else:
        counters_to_get = ','.join(counters_and_expected_values.keys())

    counters = GnbPmCounter().get_counter(counter_ids=counters_to_get, timeout=timeout)
    return counters


def validate_counters_for_detecting_muting_in_vorn_call(connection,
                                                        vorn_counters=VORN_counters,
                                                        timeout=600):
    """
    Checks the counters for detecting muting in a VoNR call.
    This function retrieves and verifies the values of specific counters to detect muting in a VoNR call.
    """
    return compare_counters_with_expected_values(vorn_counters, connection=connection, timeout=timeout)


def compare_counters_with_expected_values(counters_and_expected_values,
                                          connection=None,
                                          timeout=600):
    """ Compares the values of specified counters against their expected values.
    This function retrieves the values of specified counters and validates them against the expected
    conditions provided in the `counters_and_expected_values` dictionary. If any counter does not meet
    the expected condition, or if no data is available for a counter, a `ValueError` is raised.
    Args:
        counters_and_expected_values (dict): A dictionary where keys are counter IDs and values are dictionaries
                                             specifying the expected condition. Each dictionary contains:
                                             - 'operator' (str): The comparison operator (e.g., '==', '>', '<').
                                             - 'value' (int): The expected value to compare against.
                                             Example:
                                             {
                                                 'M55310C20019': {'operator': '==', 'value': '0'},
                                                 'M55350C20022': {'operator': '>', 'value': '0'}
                                             }
        connection (Union[AdminConnection, str], optional): The connection object or alias used to retrieve
                                                            counter values. Defaults to None.
        timeout (int, optional): The maximum time (in seconds) to wait for the counter values. Defaults to 600.
    Returns:
        list: A list of dictionaries containing counters and their values that meet the expected conditions.
              Example:
              [
                  {'BTS/MRBTS-1/NRBTS-1/NRCELL-1/NLRLC/M55310C20019': 0},
                  {'BTS/MRBTS-1/NRBTS-1/NRCELL-1/PDCPC/M55350C20022': 5}
              ]
    Raises:
        ValueError: If any counter does not meet the expected conditions or if no data is available for a counter.
                    The error message includes details about the failed counters.
    Example:
        counters_and_expected_values = {
            'M55310C20019': {'operator': '==', 'value': '0'},
            'M55350C20022': {'operator': '>', 'value': '0'}
        }
        connection = "BTS_CONNECTION_ALIAS"
        result = compare_counters_with_expected_values(counters_and_expected_values, connection)
        # Output:
        # [{'BTS/MRBTS-1/NRBTS-1/NRCELL-1/NLRLC/M55310C20019': 0},
        #  {'BTS/MRBTS-1/NRBTS-1/NRCELL-1/PDCPC/M55350C20022': 5}]
    """
    proper_cnt_value = list()
    unproper_cnt_value = list()

    cnt_resp = get_counters(counters_and_expected_values, connection, timeout)

    for cnt, expected_cnt_value in counters_and_expected_values.items():
        extracted_cnt_value = _extract_counter_values(cnt_resp, cnt)
        end_cnt_values = dict()
        if extracted_cnt_value:
            for cell_cnt in extracted_cnt_value:
                dict_path = cell_cnt.pop('dict_path')
                cell_cnt_list_value = list(cell_cnt.values())
                end_cnt_values[dict_path] = (cell_cnt_list_value[0]
                                             if all(i == cell_cnt_list_value[0]
                                                    for i in cell_cnt_list_value) else cell_cnt_list_value)
            expected_operator = expected_cnt_value['operator']
            expected_value = int(expected_cnt_value['value'])
            for end_cnt_dict, end_cnt_value in end_cnt_values.items():
                if isinstance(end_cnt_value, list):
                    unproper_cnt_value.append({end_cnt_dict: end_cnt_value,
                                               'expected': f'{expected_operator} {expected_value}',
                                               'comment': 'Counter value has changed in time'})
                else:
                    if _evaluate_condition(end_cnt_value, expected_operator, expected_value):
                        proper_cnt_value.append({dict_path: end_cnt_value})
                    else:
                        unproper_cnt_value.append({end_cnt_dict: end_cnt_value,
                                                   'expected': f'{expected_operator} {expected_value}'})
        else:
            unproper_cnt_value.append({cnt: 'No data available',
                                       'expected': f'{expected_cnt_value["operator"]} {expected_cnt_value["value"]}',
                                       'comment': 'Counter not available'})
    if len(unproper_cnt_value) > 0:
        raise ValueError('Some counters did not meet the expected conditions: {unproper_cnt_value}')

    return proper_cnt_value


def check_counters_logic(cnt_values, counters_to_verify, operator, min_val=None, max_val=None):
    """ Validates that the values of counters satisfy the logical relationship defined by the operator.
        Args:
            cnt_values (dict): A nested dictionary containing counter data to validate.
                               Example:
                                {'BTS\\MRBTS-84093\\EQM-1\\APEQM-1\\RMOD-11\\SFP-1\\SBTS_SFP_RMOD':
                                    {'counter1':
                                        {'1760956500': 5,
                                         '1760956800': 5},
                                     'counter2':
                                        {'1760956500': 41,
                                         '1760956800': 38},
                                     'counter3':
                                        {'1760956500': 46,
                                         '1760956800': 41},
                                     'counter4':
                                        {'1760956500': 214,
                                         '1760956800': 197}
                                    }
                                }
            counters_to_verify (list): A list of counter IDs to include in the validation.
                                       Example: ['counter1', 'counter2', 'counter3']
            operator (str): A comparison operator to use for validation.
                            Supported operators: '<', '>', '<=', '>=', '==', '!='.
            min_val (int, optional): A minimum value to include in the validation. Defaults to None.
            max_val (int, optional): A maximum value to include in the validation. Defaults to None.
        Returns:
            bool: True if all adjacent values satisfy the operator condition.
        Raises:
            ValueError: If any pair of adjacent values does not satisfy the operator condition. The error message
                        includes details about the failed comparisons.
            KeyError: If the provided operator is not supported.
        Example:
            cnt_values = {'BTS\\MRBTS-84093\\EQM-1\\APEQM-1\\RMOD-11\\SFP-1\\SBTS_SFP_RMOD':
                                    {'M40005C3':
                                        {'1760956500': 5,
                                         '1760956800': 5},
                                     'M40005C7':
                                        {'1760956500': 41,
                                         '1760956800': 38},
                                     'M40005C8':
                                        {'1760956500': 46,
                                         '1760956800': 41},
                                     'M40005C9':
                                        {'1760956500': 214,
                                         '1760956800': 197}
                                    }
                                }
            counters_to_verify = ['min_val', 'M40005C7', 'M40005C8', 'M40005C9', 'max_val']
            operator = '<'
            result = check_counters_logic(cnt_values, counters_to_verify, operator)
            # Output: True

            cnt_values = cnt_values = {'BTS\\MRBTS-84093\\EQM-1\\APEQM-1\\RMOD-11\\SFP-1\\SBTS_SFP_RMOD':
                                     'M40005C7':
                                        {'1760956500': 71,
                                         '1760956800': 38},
                                     'M40005C8':
                                        {'1760956500': 46,
                                         '1760956800': 41},
                                    }
                                }
            counters_to_verify = ['counter1', 'counter2']
            operator = '<'
            result = check_counters_logic(cnt_values, counters_to_verify, operator)
            # Raises ValueError: Values do not meet the expected condition:
            # Timestamp: 1760956500: error: 71 < 46,
            #     M40005C7=71, 1760956500=46
    """
    values_to_check = _prepare_data_to_compare(cnt_values, counters_to_verify, min_val, max_val)
    for timestamp, values in values_to_check.items():
        ordered_data = OrderedDict(values)
        values_list = tuple(ordered_data.values())
        keys_list = tuple(ordered_data.keys())
        failed_comparisons = list()

        for i in range(len(ordered_data) - 1):
            if not _evaluate_condition(values_list[i], operator, values_list[i + 1]):
                failed_comparisons.append(
                    f'Timestamp: {timestamp}: error: {values_list[i]} {operator} {values_list[i+1]}, '
                    f'\n    {keys_list[i]}={values_list[i]}, {keys_list[i+1]}={values_list[i+1]}'
                )
        if failed_comparisons:
            error_msg = ('Values do not meet the expected condition:\n'
                         + '\n'.join(failed_comparisons))
            raise ValueError(error_msg)

    return True


def calculate_and_compare_cnt_avg_value(cnt_values, counters_to_verify, operator, min_val=None, max_val=None):
    """ Calculates the average value of two counter values for each timestamp and validates it against optional thresholds.
    Args:
        cnt_values (dict): A dictionary where keys are timestamps and values are tuples of two counters.
                           Each tuple contains the counter name and its value.
                           Example:
                           {'BTS\\MRBTS-84093\\EQM-1\\APEQM-1\\CABINET-1\\BBMOD-6\\SFP-5\\SBTS_SFP_BBMOD':
                                {'counter1':
                                    {'1760956500': 5,
                                     '1760956800': 5},
                                'counter2':
                                    {'1760956500': 8,
                                     '1760956800': 7},
                                'counter3':
                                    {'1760956500': 12,
                                     '1760956800': 8}
                                }
                           }
        counters_to_verify (list): A list of counter IDs to include in the calculation.
                                   Example: ['counter1', 'counter2']
        operator (str): A comparison operator to use for validation.
                    Supported operators: '<', '>', '<=', '>=', '==', '!='.
        min_val (int, optional): A minimum threshold value to validate the calculated average against. Defaults to None.
        max_val (int, optional): A maximum threshold value to validate the calculated average against. Defaults to None.
    Returns:
        bool: True if all calculated averages satisfy the optional thresholds, otherwise raises a `ValueError`.
    Raises:
        ValueError: If the number of counter values for a timestamp is not exactly two, or if the calculated average
                    does not meet the specified `min_val` or `max_val` conditions.
    Example:
        cnt_values = {'BTS\\MRBTS-84093\\EQM-1\\APEQM-1\\CABINET-1\\BBMOD-6\\SFP-5\\SBTS_SFP_BBMOD':
                                {'M40007C3':
                                    {'1760956500': 5,
                                     '1760956800': 5},
                                'M40007C7':
                                    {'1760956500': 8,
                                     '1760956800': 7},
                                'M40007C9':
                                    {'1760956500': 12,
                                     '1760956800': 8}
                                }
                           }
        counters_to_verify = ['M40007C9', 'M40007C3']
        min_val = -800
        max_val = 800
        result = calculate_and_compare_cnt_avg_value(cnt_values, counters_to_verify, min_val, max_val)
        # Output: True
        cnt_values = {'BTS\\MRBTS-84093\\EQM-1\\APEQM-1\\CABINET-1\\BBMOD-6\\SFP-5\\SBTS_SFP_BBMOD':
                                {'M40007C3':
                                    {'1760956500': 5,
                                     '1760956800': 5},
                                'M40007C7':
                                    {'1760956500': 8,
                                     '1760956800': 7},
                                'M40007C9':
                                    {'1760956500': 12,
                                     '1760956800': 8}
                                }
                           }
        result = calculate_and_compare_cnt_avg_value(cnt_values, counters_to_verify, min_val=2, max_val=10)
        # Raises ValueError: Some averages did not meet the expected conditions:
        # Timestamp: 1760956500: error: 2 < 1.6
    """
    values_to_check = _prepare_data_to_compare(cnt_values, counters_to_verify)
    for timestamp, values in values_to_check.items():
        failed_comparisons = list()
        if len(values) != 2:
            raise ValueError(f'Only two values are required to perform division. Values: {values}')

        first_v = values[0][1]
        second_v = values[1][1]

        if second_v != 0:
            avg = round(first_v / second_v) if first_v != 0 else 0

            if min_val:
                if not _evaluate_condition(int(min_val), operator, avg):
                    failed_comparisons.append(
                        f'Timestamp: {timestamp}: error: {min_val} < {avg}')
            if max_val:
                if not _evaluate_condition(avg, operator, int(max_val)):
                    failed_comparisons.append(
                        f'Timestamp: {timestamp}: error: {avg} < {max_val}')

        if failed_comparisons:
            error_msg = ('Some averages did not meet the expected conditions:\n'
                         + '\n'.join(failed_comparisons))
            raise ValueError(error_msg)

    return True


def split_counter_output(input_dict, elem):
    """ Extracts data for a specific element path from a nested dictionary.
    This function searches for a specific path in a nested dictionary and retrieves the data associated with it,
    along with the hierarchical path to the element.
    Args:
        input_dict (dict): The input dictionary containing nested data.
                           Example:
                           {
                               'BTS': {
                                   'MRBTS-1': {
                                       'EQM-1': {
                                           'RMOD-11': {
                                               'SFP-1': {
                                                   'data': 'value'
                                               }
                                           }
                                       }
                                   }
                               }
                           }
        elem (tuple): A tuple representing the path of elements to search for.
                      Example: ('RMOD-11', 'SFP-1')
    Returns:
        list: A list containing a dictionary with the hierarchical path as the key and the data as the value.
              Example:
              [
                  {'BTS\\MRBTS-1\\EQM-1\\RMOD-11\\SFP-1': {'data': 'value'}}
              ]
    Raises:
        ValueError: If the specified element path is not found in the input dictionary.
    Example:
        input_dict = {
            'BTS': {
                'MRBTS-1': {
                    'EQM-1': {
                        'RMOD-11': {
                            'SFP-1': {
                                'data': 'value'
                            }
                        }
                    }
                }
            }
        }
        elem = ('RMOD-11', 'SFP-1')
        result = split_counter_output(input_dict, elem)
        # Output:
        # [{'BTS\\MRBTS-1\\EQM-1\\RMOD-11\\SFP-1': {'data': 'value'}}]
    """
    def recursive_search(data, path, current_path):
        if not path:
            return {current_path: data}

        key_to_find = path[0]
        for key, value in data.items():
            new_path = f'{current_path}\x5c{key}' if current_path else key
            if key == key_to_find:
                r = recursive_search(value, path[1:], new_path)
                return r
            elif isinstance(value, dict):
                result = recursive_search(value, path, new_path)
                if result:
                    return result

        return None

    result = recursive_search(input_dict, elem, "")
    if not result:
        raise ValueError(f'Element path {elem} not found in the input dictionary.')

    return [result]


def check_counters_value_consistency(cnt_values, counters_to_compare, expected_val=None):
    """ Validates that the values of specified counters are consistent across timestamps and optionally match an expected value.
    Args:
        cnt_values (dict): A dictionary where keys are timestamps and values are tuples of counters and their values.
                           Example:
                           {'BTS\\MRBTS-84093\\EQM-1\\APEQM-1\\CABINET-1\\BBMOD-4\\SFP-1\\LANE-1\\SBTS_SFP_BBMOD_LANE':
                                {'counter1':
                                    {'1760956500': 129,
                                     '1760956800': 0},
                                 'counter2':
                                    {'1760956500': 1489,
                                     '1760956800': 0}
                                }
                           }
        counters_to_compare (list): A list of counter IDs to include in the validation.
                                    Example: ['counter1', 'counter2']
        expected_val (int, optional): An optional value to validate against all counter values. Defaults to None.
    Returns:
        bool: True if all counter values are consistent and, if provided, match the `expected_val`.
    Raises:
        ValueError: If the counter values are inconsistent or do not match the `expected_val`.
    Example:
        cnt_values = {'BTS\\MRBTS-84093\\EQM-1\\APEQM-1\\CABINET-1\\BBMOD-4\\SFP-1\\LANE-1\\SBTS_SFP_BBMOD_LANE':
                                {'M40015C14':
                                    {'1760956500': 0,
                                     '1760956800': 0},
                                 'M40015C15':
                                    {'1760956500': 0,
                                     '1760956800': 0}
                                }
                           }
        counters_to_compare = ['M40015C14', 'M40015C15']
        expected_val = 0
        result = check_counters_value_consistency(cnt_values, counters_to_compare, expected_val)
        # Output: True

        cnt_values = {'BTS\\MRBTS-84093\\EQM-1\\APEQM-1\\CABINET-1\\BBMOD-4\\SFP-1\\LANE-1\\SBTS_SFP_BBMOD_LANE':
                                {'M40015C14':
                                    {'1760956500': 1,
                                     '1760956800': 0},
                                 'M40015C15':
                                    {'1760956500': 0,
                                     '1760956800': 0}
                                }
                           }
        result = check_counters_value_consistency(cnt_values, counters_to_compare)
        # Raises ValueError: Values do not meet the expected condition:
        # Timestamp: 1760956500: error: 1 != 0
    """
    values_to_check = _prepare_data_to_compare(cnt_values, counters_to_compare)
    for timestamp, values in values_to_check.items():
        values_list = [item[1] for item in values]
        failed_comparisons = list()

        if len(set(values_list)) != 1:
            failed_comparisons.append(f'Timestamp: {timestamp}: error: {" != ".join(map(str, values_list))}')
        if expected_val is not None:
            for value in values_list:
                if int(value) != int(expected_val):
                    failed_comparisons.append(f'{value} != {expected_val}')
        if failed_comparisons:
            error_msg = 'Values do not meet the expected condition:\n' + '\n'.join(failed_comparisons)
            raise ValueError(error_msg)

    return True
